def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find maximal horizontal and vertical runs of 5.
    bars = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 5 and (c == 0 or grid[r][c-1] != 5):
                end = c
                while end + 1 < w and grid[r][end+1] == 5:
                    end += 1
                if end > c:
                    bars.append(("h", r, c, end))
                c = end + 1
            else:
                c += 1

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 5 and (r == 0 or grid[r-1][c] != 5):
                end = r
                while end + 1 < h and grid[end+1][c] == 5:
                    end += 1
                if end > r:
                    bars.append(("v", c, r, end))
                r = end + 1
            else:
                r += 1

    for orient, fixed, start, end in bars:
        if orient == "h":
            # A vertical color strip at either end of the bar is repeated
            # across its length.
            for c in (start, end):
                for dr in (-1, 1):
                    colors = []
                    rr = fixed + dr
                    while 0 <= rr < h and grid[rr][c] not in (0, 5):
                        colors.append((rr, grid[rr][c]))
                        rr += dr
                    if colors:
                        for rr, color in colors:
                            for cc in range(start, end + 1):
                                out[rr][cc] = color
                        break
                else:
                    continue
                break

        else:
            # Find a repeated horizontal motif next to the vertical bar.
            for dc in (-1, 1):
                first_col = fixed + dc
                if not 0 <= first_col < w:
                    continue
                active = [
                    rr for rr in range(start, end + 1)
                    if grid[rr][first_col] not in (0, 5)
                ]
                if not active:
                    continue

                # The contiguous run of motif rows determines its period.
                lo = min(active)
                hi = max(active)
                while lo > start and grid[lo-1][first_col] not in (0, 5):
                    lo -= 1
                while hi < end and grid[hi+1][first_col] not in (0, 5):
                    hi += 1
                period = hi - lo + 1

                cols = []
                cc = first_col
                step = 1 if dc == 1 else -1
                while 0 <= cc < w and any(grid[rr][cc] not in (0, 5) for rr in range(lo, hi + 1)):
                    cols.append(cc)
                    cc += step

                for rr in range(start, end + 1):
                    src = lo + ((rr - lo) % period)
                    for j, cc in enumerate(cols):
                        color = grid[src][cc]
                        if color not in (0, 5):
                            out[rr][cc] = color
                break

    return out
